using System.Security.Claims;
using EmployeeMonitoringAPI.Data;
using EmployeeMonitoringAPI.DTOs;
using EmployeeMonitoringAPI.Interfaces;
using EmployeeMonitoringAPI.Models;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
namespace EmployeeMonitoringAPI.Controllers;
[ApiController,Route("api/hr/promotion-workflow"),Authorize(Roles="HR")]
public sealed class HrPromotionController(ApplicationDbContext db,IAuditService audit):ControllerBase
{
 int HrId()=>int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);IQueryable<User>Owned()=>db.Users.Where(x=>x.AssignedHrId==HrId()&&(x.Role=="Employee"||x.Role=="Manager"));
 [HttpGet("performance")]public async Task<IActionResult>Performance(int?year=null,string quarter="Q1",int?departmentId=null,string?classification=null,string sort="rating",int page=1,int pageSize=10){if(quarter is not("Q1"or"Q2"or"Q3"or"Q4"))return BadRequest(new{message="Quarter must be Q1-Q4"});var y=year??DateTime.UtcNow.Year;var q=Owned().Include(x=>x.Department).Include(x=>x.Manager).AsQueryable();if(departmentId.HasValue)q=q.Where(x=>x.DepartmentId==departmentId);var users=await q.ToListAsync();var ids=users.Select(x=>x.UserId).ToList();var reviews=await db.PerformanceReviews.Where(x=>ids.Contains(x.EmployeeId)&&x.Year==y&&x.Quarter==quarter).ToListAsync();var decisions=await db.PromotionHistories.Where(x=>ids.Contains(x.UserId)&&x.Year==y&&x.Quarter==quarter).ToListAsync();var rows=users.Select(u=>{var r=reviews.FirstOrDefault(x=>x.EmployeeId==u.UserId);var d=decisions.FirstOrDefault(x=>x.UserId==u.UserId);var recommended=r?.PromotionRecommendation=="Recommended";var eligible=r!=null&&r.IsReleased&&r.Rating>0&&!string.IsNullOrWhiteSpace(r.ManagerRemarks)&&recommended&&!string.IsNullOrWhiteSpace(r.RecommendedDesignation)&&u.IsActive&&d==null;var reason=d!=null?d.Status:r==null||!r.IsReleased?"Review Pending":!recommended?"Not Recommended":eligible?"Recommended":"Not Eligible";return new{u.UserId,u.FullName,u.Role,department=u.Department?.Name,managerName=u.Role=="Employee"?u.Manager?.FullName:null,rating=r?.Rating,status=r==null?"Not Submitted":r.IsReleased?"Finalized":"Draft",r?.PromotionRecommendation,r?.RecommendedDesignation,r?.Goals,r?.Kpis,r?.ManagerRemarks,classification=(r?.Rating??0)>=4?"Top Performer":r!=null&&r.Rating<2.5m?"Low Performer":"Core Performer",promotionEligible=eligible,promotionState=reason,decisionId=d?.PromotionHistoryId};}).ToList();if(!string.IsNullOrWhiteSpace(classification))rows=rows.Where(x=>x.classification==classification).ToList();rows=sort=="name"?rows.OrderBy(x=>x.FullName).ToList():rows.OrderByDescending(x=>x.rating??0).ToList();var total=rows.Count;page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,5,100);var paged=rows.Skip((page-1)*pageSize).Take(pageSize);var depts=rows.GroupBy(x=>x.department??"Unassigned").Select(g=>new{department=g.Key,people=g.Count(),averageRating=g.Any(x=>x.rating.HasValue)?Math.Round(g.Where(x=>x.rating.HasValue).Average(x=>x.rating!.Value),2):0,topPerformers=g.Count(x=>x.classification=="Top Performer"),lowPerformers=g.Count(x=>x.classification=="Low Performer")});return Ok(new{items=paged,departmentKpis=depts,summary=new{reviewed=reviews.Count,topPerformers=rows.Count(x=>x.classification=="Top Performer"),lowPerformers=rows.Count(x=>x.classification=="Low Performer"),promotions=rows.Count(x=>x.promotionEligible)},totalCount=total,page,pageSize,totalPages=(int)Math.Ceiling(total/(double)pageSize)});}
 [HttpPost("decisions")]public async Task<IActionResult>Decision(HrPromotionDecisionDto dto){var user=await Owned().FirstOrDefaultAsync(x=>x.UserId==dto.UserId);if(user==null)return NotFound(new{message="Owned active person not found"});if(!user.IsActive)return Conflict(new{message="Inactive people are not eligible"});var review=await db.PerformanceReviews.FirstOrDefaultAsync(x=>x.EmployeeId==dto.UserId&&x.Year==dto.Year&&x.Quarter==dto.Quarter);if(review==null||!review.IsReleased)return Conflict(new{message="A finalized quarterly review is required"});if(review.Rating<=0||string.IsNullOrWhiteSpace(review.ManagerRemarks))return Conflict(new{message="Rating and manager remarks are required"});if(review.PromotionRecommendation!="Recommended"||string.IsNullOrWhiteSpace(review.RecommendedDesignation))return Conflict(new{message="An explicit recommendation and recommended designation are required"});if(await db.PromotionHistories.AnyAsync(x=>x.UserId==dto.UserId&&x.Year==dto.Year&&x.Quarter==dto.Quarter))return Conflict(new{message="A promotion decision already exists for this quarter"});if(dto.Decision=="Rejected"&&string.IsNullOrWhiteSpace(dto.Remarks))return BadRequest(new{message="Rejection remarks are required"});if(dto.Decision=="Approved"&&(!dto.EffectiveDate.HasValue||dto.EffectiveDate.Value.Date<DateTime.UtcNow.Date))return BadRequest(new{message="A current or future effective date is required"});await using var tx=await db.Database.BeginTransactionAsync();var old=user.Designation??"";var history=new PromotionHistory{UserId=user.UserId,Year=dto.Year,Quarter=dto.Quarter,Status=dto.Decision,FromDesignation=old,ToDesignation=review.RecommendedDesignation,ApprovedDesignation=dto.Decision=="Approved"?review.RecommendedDesignation:"",ManagerRecommendation=review.PromotionRecommendation,RecommendedById=review.ReviewerId,EffectiveDate=dto.EffectiveDate?.Date??DateTime.UtcNow.Date,ApprovedById=HrId(),DecisionDate=DateTime.UtcNow,Remarks=dto.Remarks?.Trim()??""};if(dto.Decision=="Approved")user.Designation=history.ApprovedDesignation;db.Add(history);db.Add(new Notification{UserId=user.UserId,Title="Promotion "+dto.Decision.ToLowerInvariant(),Message=dto.Decision=="Approved"?$"Your designation was updated to {history.ApprovedDesignation}.":$"Your promotion recommendation was rejected. {history.Remarks}",Type="Promotion",RelatedUrl="/employee/performance",DeduplicationKey=$"promotion:{user.UserId}:{dto.Year}:{dto.Quarter}:{dto.Decision}"});if(dto.Decision=="Rejected"&&review.ReviewerId.HasValue)db.Add(new Notification{UserId=review.ReviewerId.Value,Title="Promotion recommendation rejected",Message=$"The recommendation for {user.FullName} was rejected. {history.Remarks}",Type="Promotion",RelatedUrl="/manager/performance",DeduplicationKey=$"promotion-manager:{user.UserId}:{dto.Year}:{dto.Quarter}:rejected"});await db.SaveChangesAsync();await tx.CommitAsync();await audit.RecordAsync("Promotion"+dto.Decision,"User",user.UserId.ToString(),actorUserId:HrId(),safeMetadata:new{dto.Year,dto.Quarter,OldDesignation=old,history.ApprovedDesignation});return Ok(new{message="Promotion "+dto.Decision.ToLowerInvariant()});}
}
